import re
import os
from pathlib import Path
import glob

def task_func(directory_path: str, regex_pattern: str = r'\\(.+?\\)|\\w') -> dict:
    """
    Extract matches from all text files in a directory.

    The default pattern is normalized to support the intended semantics:
    - content inside parentheses is returned as a single match
    - characters outside parentheses are returned individually (as matched by \w)
    """
    directory = Path(directory_path)
    if not directory.is_dir():
        return {}

    # Normalize common double-escaped regex input so the intended pattern works
    # (e.g. r'\\(.+?\\)|\\w' -> r'\((.+?)\)|\w')
    pattern = regex_pattern
    if "\\\\" in pattern:
        normalized = pattern.replace("\\\\", "\\")
        try:
            re.compile(normalized)
            pattern = normalized
        except re.error:
            pass

    try:
        regex = re.compile(pattern)
    except re.error:
        return {}

    results = {}

    for file_name in sorted(glob.glob(os.path.join(directory_path, "*.txt"))):
        file_path = Path(file_name)
        if not file_path.is_file():
            continue

        try:
            text = file_path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        matches = []
        for match in regex.finditer(text):
            groups = match.groups()
            if groups:
                non_none_groups = [g for g in groups if g is not None]
                if len(non_none_groups) == 1:
                    matches.append(non_none_groups[0])
                elif non_none_groups:
                    matches.append("".join(non_none_groups))
                else:
                    matches.append(match.group(0))
            else:
                matches.append(match.group(0))

        results[file_path.name] = matches

    return results
